import cv2, numpy as np, os, json
cap = cv2.VideoCapture(\"media/mv_lazy.mp4\")
fps = cap.get(cv2.CAP_PROP_FPS)
n = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT)); w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
y0 = int(h*0.82)
vals=[]
frames=[]
i=0
while True:
    ok, fr = cap.read()
    if not ok: break
    crop = fr[y0:h, :, :]
    gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
    # white text: bright pixels
    mask = (gray>200).astype(np.uint8)
    # focus bottom band
    cnt = int(mask.sum())
    vals.append(cnt)
    frames.append(i)
    i+=1
cap.release()
vals=np.array(vals)
print(\"frames\", n, \"fps\", fps, \"max\", vals.max(), \"median\", np.median(vals))
# threshold
thr = max(80, np.percentile(vals, 40)*1.5)
present = vals > thr
# runs
runs=[]; start=None
for idx,p in enumerate(present):
    if p and start is None: start=idx
    if not p and start is not None:
        runs.append((start, idx-1)); start=None
if start is not None: runs.append((start, len(present)-1))
# merge runs with gaps < 0.25s
merged=[]
for a,b in runs:
    if merged and (a-merged[-1][1]) < fps*0.25:
        merged[-1]=(merged[-1][0], b)
    else: merged.append((a,b))
out=[]
for a,b in merged:
    if (b-a) < fps*0.3: continue
    out.append({\"start\":round(a/fps,2),\"end\":round((b+1)/fps,2),\"mid\":round((a+b)/2/fps,2)})
print(json.dumps(out, ensure_ascii=False, indent=1))
json.dump(out, open(\"output/work/lazy_sub_runs.json\",\"w\"), indent=1)
